// VectorDistanceFunctions: Velox scalar function registration for vector
// distance functions (l2_distance, cosine_distance, inner_product).
//
// Wraps the SIMD-optimized VectorDistance.h functions as Velox VectorFunctions
// so they can be called from Substrait plans generated by the Java planner.
//
// Signatures: ARRAY<REAL/DOUBLE> pairs -> DOUBLE.
//
// Placement: vector/ — Native vector index computation components.
#pragma once

#include <cstddef>

namespace pangrova::vector {

// Validates the fixed-width VECTOR contract. Dimension drift is a query error,
// never a nullable value, because NULL would silently corrupt Top-K ordering.
void validateVectorDimensions(std::size_t left_size, std::size_t right_size);

// Register l2_distance, cosine_distance, inner_product, and
// pangrova_cosine_similarity as Velox scalar VectorFunctions. The Pangrova
// alias does not overwrite Velox's built-in cosine_similarity signatures.
void registerVectorDistanceFunctions();

}  // namespace pangrova::vector
